SELECT
*
, (
	SELECT
		CASE
			WHEN LOCGOV.LOCGOV_CODE = LOCGOV.UPPER_LOCGOV_CODE
				THEN LOCGOV.UPPER_LOCGOV_NM
			ELSE
				CONCAT(LOCGOV.UPPER_LOCGOV_NM, ' ', LOCGOV.LOCGOV_NM)
			END
	FROM G_LOCGOV LOCGOV
	WHERE LOCGOV.LOCGOV_CODE = F.LOCGOV_CODE) AS LOCGOV_NAME
FROM OP_FEATURED F


		AND FEATURED_TYPE = #{featuredType}


 		AND FEATURED_ID = #{featuredId}


		AND FEATURED_URL = #{featuredUrl}


		AND FEATURED_FLAG = #{featuredFlag}


		AND DISPLAY_LIST_FLAG = #{displayListFlag}


		AND LOCGOV_CODE = #{locgovCode}

